/* Local-only decoder. Input pixels never leave this worker/browser. LGPL library is separately replaceable. */
importScripts('heic-libheif-1.23.5.js');
self.onmessage=async({data})=>{let frames=[];try{const factory=typeof libheif==='function'?libheif:libheif.default;const library=libheif.HeifDecoder?libheif:await factory();const decoder=new library.HeifDecoder();frames=decoder.decode(data);if(!frames.length)throw Error('Geen foto');const frame=frames[0],width=frame.get_width(),height=frame.get_height();if(width<1||height<1||width*height>40000000)throw Error('Foto te groot');const target={width,height,data:new Uint8ClampedArray(width*height*4)};await new Promise((resolve,reject)=>frame.display(target,value=>value?resolve(value):reject(Error('Decoderen mislukt'))));self.postMessage({ok:true,width,height,pixels:target.data},[target.data.buffer]);}catch{self.postMessage({ok:false});}finally{for(const frame of frames)frame.free?.();}};
